"""Meridian CRM 4.2 batch error-handling runner migration."""

from typing import Any, Callable


def run_jobs(jobs: list[dict], executor: Callable[[dict], Any]) -> list[dict]:
    """Run scheduled jobs sequentially using legacy ON_ERROR semantics."""
    run_log: list[dict] = []

    for job in jobs:
        on_error = job["on_error"]
        policy = on_error["policy"]

        if policy == "RETRY":
            attempts = 0
            succeeded = False

            for _ in range(on_error["retries"] + 1):
                attempts += 1
                try:
                    executor(job)
                except Exception:
                    continue
                else:
                    succeeded = True
                    break

            if succeeded:
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": attempts,
                        "outcome": "ok",
                        "audits": [],
                    }
                )
                continue

            run_log.append(
                {
                    "name": job["name"],
                    "attempts": attempts,
                    "outcome": "abort",
                    "audits": [],
                }
            )
            break

        try:
            executor(job)
        except Exception:
            if policy == "CONTINUE":
                run_log.append(
                    {
                        "name": job["name"],
                        "attempts": 1,
                        "outcome": "skip",
                        "audits": ["BATCH_ROWSKIP"],
                    }
                )
                continue

            run_log.append(
                {
                    "name": job["name"],
                    "attempts": 1,
                    "outcome": "abort",
                    "audits": [],
                }
            )
            break
        else:
            run_log.append(
                {
                    "name": job["name"],
                    "attempts": 1,
                    "outcome": "ok",
                    "audits": [],
                }
            )

    return run_log
